export function* range(start, end, step = 1) {
  // your code here
}

test_suite:
test('single arg yields 0 to end exclusive', () => {
  expect([...range(4)]).toEqual([0, 1, 2, 3]);
});

test('two args yields start to end exclusive', () => {
  expect([...range(2, 5)]).toEqual([2, 3, 4]);
});

test('step arg skips values', () => {
  expect([...range(0, 10, 3)]).toEqual([0, 3, 6, 9]);
});

test('empty range when start >= end', () => {
  expect([...range(5, 3)]).toEqual([]);
});

// __hidden__
test('step of 2 works correctly', () => {
  expect([...range(1, 8, 2)]).toEqual([1, 3, 5, 7]);
});

solution:
export function* range(start, end, step = 1) {
  if (end === undefined) { end = start; start = 0; }
  for (let i = start; i < end; i += step) {
    yield i;
  }
}
